package java.text;
import java.util.Locale;
public abstract class NumberFormat extends Format {
 protected int minFrac=0,maxFrac=3,minInt=1;protected boolean grouping=true;
 public static NumberFormat getInstance(){return getInstance(Locale.getDefault());}public static NumberFormat getInstance(Locale l){return new DecimalFormat("#,##0.###",new DecimalFormatSymbols(l));}public static NumberFormat getNumberInstance(){return getInstance();}public static NumberFormat getNumberInstance(Locale l){return getInstance(l);}public static NumberFormat getIntegerInstance(){return getIntegerInstance(Locale.getDefault());}public static NumberFormat getIntegerInstance(Locale l){return new DecimalFormat("#,##0",new DecimalFormatSymbols(l));}public static NumberFormat getPercentInstance(){return getPercentInstance(Locale.getDefault());}public static NumberFormat getPercentInstance(Locale l){return new DecimalFormat("#,##0%",new DecimalFormatSymbols(l));}public static NumberFormat getCurrencyInstance(){return getCurrencyInstance(Locale.getDefault());}public static NumberFormat getCurrencyInstance(Locale l){return new DecimalFormat("¤#,##0.00",new DecimalFormatSymbols(l));}
 public final String format(double v){return format(v,new StringBuffer(),new FieldPosition(0)).toString();}public final String format(long v){return format(v,new StringBuffer(),new FieldPosition(0)).toString();}public abstract StringBuffer format(double v,StringBuffer b,FieldPosition p);public abstract StringBuffer format(long v,StringBuffer b,FieldPosition p);
 public StringBuffer format(Object v,StringBuffer b,FieldPosition p){if(!(v instanceof Number))throw new IllegalArgumentException("Cannot format given Object as a Number");if(v instanceof Long||v instanceof Integer||v instanceof Short||v instanceof Byte)return format(((Number)v).longValue(),b,p);return format(((Number)v).doubleValue(),b,p);}
 public abstract Number parse(String s,ParsePosition p);public Number parse(String s)throws ParseException{ParsePosition p=new ParsePosition(0);Number n=parse(s,p);if(p.getIndex()==0)throw new ParseException("Unparseable number: \""+s+"\"",p.getErrorIndex());return n;}public Object parseObject(String s,ParsePosition p){return parse(s,p);}
 public void setMinimumFractionDigits(int n){minFrac=Math.max(0,n);if(maxFrac<minFrac)maxFrac=minFrac;}public void setMaximumFractionDigits(int n){maxFrac=Math.max(0,n);if(minFrac>maxFrac)minFrac=maxFrac;}public void setMinimumIntegerDigits(int n){minInt=Math.max(0,n);}public void setGroupingUsed(boolean v){grouping=v;}public boolean isGroupingUsed(){return grouping;}public int getMinimumFractionDigits(){return minFrac;}public int getMaximumFractionDigits(){return maxFrac;}public int getMinimumIntegerDigits(){return minInt;}
}
